{
  "id": "R1",
  "summary_ko": "구식의 이상해 보이는 비디오 카메라가 어떻게 사용되는지 불분명함.",
  "claims": [
    {
      "id": "R1.S1",
      "evidence": "Unclear how old fashioned off-looking video camera is meant to be used",
      "symptom_ko": "구식의 이상하게 보이는 비디오 카메라의 사용 방식이 불분명함",
      "is_anomaly": true,
      "specificity": "broad",
      "target_evidence": "old fashioned off-looking video camera",
      "explicit_detail_evidence": [],
      "missing_details_ko": "비디오 카메라가 구체적으로 어떻게 이상하게 생겼는지, 어떤 구조나 사용 메커니즘에서 오류가 발생하는지 명시되지 않음"
    }
  ]
}

{
  "id": "R2",
  "summary_ko": "카메라가 뒤로 물러서지 않고 반(수업) 쪽으로 전진함",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "Camera advancing towards the class, not backing up",
      "symptom_ko": "카메라가 뒤로 물러서지 않고 수업 쪽으로 전진함",
      "is_anomaly": false,
      "specificity": "neutral",
      "target_evidence": "Camera",
      "explicit_detail_evidence": [],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R3",
  "summary_ko": "카메라가 움직임에 따라 앞쪽 파란 셔츠를 입은 두 번째 소녀가 새로운 각도와 위치에 나타남",
  "claims": [
    {
      "id": "R3.S1",
      "evidence": "Second girl in front, blue shirt, appears in a new angle and position as camera moves",
      "symptom_ko": "카메라 이동에 따라 앞쪽에 있는 파란 셔츠를 입은 두 번째 소녀가 새로운 각도와 위치에서 나타남",
      "is_anomaly": false,
      "specificity": "neutral",
      "target_evidence": "Second girl in front, blue shirt",
      "explicit_detail_evidence": [],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R4",
  "summary_ko": "오른쪽 가장자리에서 천장 텍스처가 나타났다가 사라짐",
  "claims": [
    {
      "id": "R4.S1",
      "evidence": "Ceiling texture appears and disappears on right edge",
      "symptom_ko": "오른쪽 가장자리에서 천장 텍스처가 나타났다 사라지는 현상이 발생함",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "Ceiling texture",
      "explicit_detail_evidence": [
        "appears and disappears on right edge"
      ],
      "missing_details_ko": ""
    }
  ]
}

